-- Walker

-- Application bindings
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.bind("SUPER + RETURN", hl.dsp.exec_cmd("uwsm-app -- xdg-terminal-exec --dir=\"$(syna-cmd-terminal-cwd)\""), { description = "Terminal" })
hl.bind("SUPER + SHIFT + F", hl.dsp.exec_cmd("uwsm-app -- nautilus --new-window"), { description = "File manager" })
hl.bind("SUPER + SHIFT + B", hl.dsp.exec_cmd("syna-launch-browser"), { description = "Browser" })
hl.bind("SUPER + SHIFT + ALT + B", hl.dsp.exec_cmd("syna-launch-browser --private"), { description = "Browser (private)" })
hl.bind("SUPER + SHIFT + M", hl.dsp.exec_cmd("syna-launch-or-focus spotify"), { description = "Music" })
hl.bind("SUPER + SHIFT + N", hl.dsp.exec_cmd("syna-launch-editor"), { description = "Editor" })
hl.bind("SUPER + SHIFT + T", hl.dsp.exec_cmd("syna-launch-tui btop"), { description = "Activity" })
hl.bind("SUPER + SHIFT + D", hl.dsp.exec_cmd("syna-launch-tui lazydocker"), { description = "Docker" })
hl.bind("SUPER + SHIFT + G", hl.dsp.exec_cmd("syna-launch-or-focus ^signal$ \"uwsm-app -- signal-desktop\""), { description = "Signal" })
hl.bind("SUPER + SHIFT + O", hl.dsp.exec_cmd("syna-launch-or-focus ^obsidian$ \"uwsm-app -- obsidian -disable-gpu --enable-wayland-ime\""), { description = "Obsidian" })
hl.bind("SUPER + SHIFT + W", hl.dsp.exec_cmd("uwsm-app -- typora --enable-wayland-ime"), { description = "Typora" })
hl.bind("SUPER + SHIFT + SLASH", hl.dsp.exec_cmd("uwsm-app -- 1password"), { description = "Passwords" })

-- If your web app url contains #, type it as ## to prevent hyprland treating it as a comment
hl.bind("SUPER + SHIFT + A", hl.dsp.exec_cmd("syna-launch-webapp \"https://chatgpt.com\""), { description = "ChatGPT" })
--bindd = SUPER SHIFT ALT, A, Grok, exec, syna-launch-webapp "https://grok.com"
--bindd = SUPER SHIFT, C, Calendar, exec, syna-launch-webapp "https://app.hey.com/calendar/weeks/"
--bindd = SUPER SHIFT, E, Email, exec, syna-launch-webapp "https://app.hey.com"
hl.bind("SUPER + SHIFT + Y", hl.dsp.exec_cmd("syna-launch-webapp \"https://youtube.com/\""), { description = "YouTube" })
hl.bind("SUPER + SHIFT + ALT + G", hl.dsp.exec_cmd("syna-launch-or-focus-webapp WhatsApp \"https://web.whatsapp.com/\""), { description = "WhatsApp" })
hl.bind("SUPER + SHIFT + CTRL + G", hl.dsp.exec_cmd("syna-launch-or-focus-webapp \"Google Messages\" \"https://messages.google.com/web/conversations\""), { description = "Google Messages" })
--bindd = SUPER SHIFT, P, Google Photos, exec, syna-launch-or-focus-webapp "Google Photos" "https://photos.google.com/"
--bindd = SUPER SHIFT, X, X, exec, syna-launch-webapp "https://x.com/"
--bindd = SUPER SHIFT ALT, X, X Post, exec, syna-launch-webapp "https://x.com/compose/post"

-- Screenshots with SHIFT + Delete
hl.bind("SHIFT + Delete", hl.dsp.exec_cmd("~/.local/bin/rice/syna-cmd-screenshot"), { description = "Screenshot of region" })
hl.bind("SHIFT + CTRL + Delete", hl.dsp.exec_cmd("~/.local/bin/rice/syna-cmd-screenshot window"), { description = "Screenshot of window" })
hl.bind("SHIFT + ALT + Delete", hl.dsp.exec_cmd("~/.local/bin/rice/syna-cmd-screenshot output"), { description = "Screenshot of display" })

-- Apps
-- Gaming on workspace 3 (primary display); replace the inherited grouping bind.
hl.unbind("SUPER + G")  -- remove the inherited grouping bind (rice defaults bindings/tiling-v2)
hl.bind("SUPER + CTRL + G", hl.dsp.group.toggle(), { description = "Toggle window grouping" })
hl.bind("SUPER + G", hl.dsp.exec_cmd("~/.local/bin/rice/syna-launch-gaming"), { description = "Steam Big Picture on workspace 3" })

-- Custom Keybindings
--bind = SUPER, B, exec, firefox

-- One application-launcher binding, after inherited defaults.
hl.unbind("SUPER + SPACE")  -- remove the inherited launcher bind (rice defaults bindings/utilities)
hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("~/.local/bin/rice/syna-launch-walker"), { description = "Launch apps" })
